---ShowTrialLimitValueChange
---展示 每周奖励 上限提升
function BattleEndTrialLvDialog:ShowTrialLimitValueChange()
    self.coShowValueChange = cs_coroutine.start(function()
        self.Txt_LimitValue.text = tostring(self.trialRewardLimitValue)
        self.Txt_LimitUpValue.text = string.format(" + %d", self.trialRewardLimitUpValue)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.5))
        while self.trialRewardLimitUpValue > 0 do
            local clipValue = math.random(1, 6)
            self.trialRewardLimitValue = self.trialRewardLimitValue + clipValue
            self.trialRewardLimitUpValue = self.trialRewardLimitUpValue - clipValue
            self.Txt_LimitValue.text = tostring(self.trialRewardLimitValue)
            self.Txt_LimitUpValue.text = string.format(" + %d", self.trialRewardLimitUpValue)
            cs_coroutine.yield_return()
        end
        self:ShowResultValue()
        self.coShowValueChange = nil
    end)
end

